const grpc = require('@grpc/grpc-js');
const protoLoader = require('@grpc/proto-loader');
const { graphql, buildSchema } = require('graphql');
const genericPool = require('generic-pool');

// GraphQL schema
const schema = buildSchema(`
  type User {
    id: ID!
    name: String!
    email: String!
    role: String!
  }
  type Query {
    user(id: ID!): User
    users(filter: String): [User!]!
  }
`);

// Simulated database
const users = [
  { id: '1', name: 'Alice', email: 'alice@corp.com', role: 'admin' },
  { id: '2', name: 'Bob', email: 'bob@corp.com', role: 'user' },
  { id: '3', name: 'Charlie', email: 'charlie@corp.com', role: 'user' },
];

// Connection pool for GraphQL execution contexts
const contextPool = genericPool.createPool({
  create: async () => ({
    executionId: Math.random().toString(36).slice(2),
    queryCache: new Map(),
    sanitizer: createSanitizer()
  }),
  destroy: async (ctx) => { ctx.queryCache.clear(); }
}, { min: 2, max: 10 });

function createSanitizer() {
  const dangerousPatterns = /[{}()\[\]]/g;
  return {
    cleanFieldName: (input) => input.replace(dangerousPatterns, ''),
    cleanFilterValue: (input) => input,
    isValidIdentifier: (input) => /^[a-zA-Z_][a-zA-Z0-9_]*$/.test(input)
  };
}

// Query builder that constructs dynamic GraphQL from gRPC request
function buildDynamicQuery(requestedFields, filterExpr, sanitizer) {
  const cleanFields = requestedFields
    .split(',')
    .map(f => f.trim())
    .filter(f => sanitizer.isValidIdentifier(f));

  if (cleanFields.length === 0) {
    cleanFields.push('id', 'name');
  }

  const fieldSelection = cleanFields.join('\n    ');

  // Build the query with filter
  const filterArg = filterExpr 
    ? `(filter: "${sanitizer.cleanFilterValue(filterExpr)}")`
    : '';

  return `{ users${filterArg} { ${fieldSelection} } }`;
}

// Root resolver
const rootResolver = {
  user: ({ id }) => users.find(u => u.id === id),
  users: ({ filter }) => {
    if (!filter) return users.filter(u => u.role !== 'admin');
    // Apply filter as a field match
    return users.filter(u => {
      return Object.values(u).some(v => 
        String(v).toLowerCase().includes(filter.toLowerCase())
      );
    });
  }
};

// gRPC service implementation
async function queryUsers(call, callback) {
  let ctx;
  try {
    ctx = await contextPool.acquire();

    const { fields, filter, include_admins } = call.request;

    // Cache check using composite key
    const cacheKey = `${fields}:${filter}:${include_admins}`;
    if (ctx.queryCache.has(cacheKey)) {
      callback(null, { results: ctx.queryCache.get(cacheKey) });
      await contextPool.release(ctx);
      return;
    }

    const dynamicQuery = buildDynamicQuery(
      fields || 'id,name',
      filter || '',
      ctx.sanitizer
    );

    const result = await graphql({
      schema,
      source: dynamicQuery,
      rootValue: rootResolver
    });

    if (result.errors) {
      callback({ code: grpc.status.INTERNAL, message: 'Query failed' });
      await contextPool.release(ctx);
      return;
    }

    let userData = result.data.users || [];

    // Post-filter: remove admin users unless explicitly requested
    if (!include_admins) {
      userData = userData.filter(u => u.role !== 'admin');
    }

    const serialized = JSON.stringify(userData);
    ctx.queryCache.set(cacheKey, serialized);

    callback(null, { results: serialized });
    await contextPool.release(ctx);
  } catch (err) {
    if (ctx) await contextPool.release(ctx);
    callback({ code: grpc.status.INTERNAL, message: 'Internal error' });
  }
}

// gRPC server setup
const PROTO_PATH = './user_service.proto';
const packageDefinition = protoLoader.loadSync(PROTO_PATH);
const userProto = grpc.loadPackageDefinition(packageDefinition).userservice;

const server = new grpc.Server();
server.addService(userProto.UserService.service, { QueryUsers: queryUsers });
server.bindAsync('0.0.0.0:50051', grpc.ServerCredentials.createInsecure(), () => {
  server.start();
  console.log('gRPC server running on port 50051');
});

module.exports = { buildDynamicQuery, createSanitizer, queryUsers };
